184: onMount(() => {
185: 	const interval = window.setInterval(() => {
186: 		now = Date.now();
187: 	}, 1000);
188: 	return () => window.clearInterval(interval);
189: });
190: 
191: function fullName(member: DiscordDoctorMemberSummary): string {
192: 	return `${member.firstName} ${member.lastName}`;
193: }
194: 
195: function joinedAtTime(row: DiscordDoctorServerMember): number | null {
196: 	if (!row.joinedAt) return null;
197: 	const time = Date.parse(row.joinedAt);
198: 	return Number.isNaN(time) ? null : time;
199: }
200: 
201: function doctorGlobalFilter(
202: 	row: Row<DiscordDoctorServerMember>,
203: 	_columnId: string,
204: 	filterValue: string,
205: ): boolean {
206: 	const needle = filterValue.trim().toLowerCase();
207: 	if (!needle) return true;
208: 	const account = row.original;
209: 	return (
210: 		account.displayName.toLowerCase().includes(needle) ||
211: 		account.username.toLowerCase().includes(needle) ||
212: 		Boolean(
213: 			account.member && fullName(account.member).toLowerCase().includes(needle),
214: 		)
215: 	);
216: }
217: 
218: function sortByJoinedAt(
219: 	a: Row<DiscordDoctorServerMember>,
220: 	b: Row<DiscordDoctorServerMember>,
221: ): number {
222: 	const aTime = joinedAtTime(a.original);
223: 	const bTime = joinedAtTime(b.original);
224: 	if (aTime === null && bTime === null) return 0;
225: 	if (aTime === null) return 1;
226: 	if (bTime === null) return -1;
227: 	return aTime - bTime;
228: }
229: 
230: function formatJoinedAt(value: string | null): string {
231: 	if (!value) return "Join date unavailable";
232: 	const date = new Date(value);
233: 	if (Number.isNaN(date.valueOf())) return "Join date unavailable";
234: 	return `Joined ${formatDublinDate(value)}`;
235: }
236: 
237: function outcomeStyle(outcome: DiscordDoctorKickResult["outcome"]): string {
238: 	switch (outcome) {
239: 		case "kicked":
240: 			return "border-primary/30 bg-primary/10 text-primary";
241: 		case "already_left":
242: 			return "border-primary/25 bg-primary/5 text-foreground";
243: 		case "refused":
244: 			return "border-secondary bg-secondary/20 text-foreground";
245: 		case "failed":
246: 			return "border-destructive/30 bg-destructive/10 text-destructive";
247: 	}
248: }
