539: 	const context = {
540: 		title: "",
541: 		date,
542: 		startTime: training.schedule.startTime,
543: 		endTime: training.schedule.endTime,
544: 	};
545: 	const title = renderCopy(titleSource, context);
546: 	const rendered = renderMessage(messageSource, training.everyone, {
547: 		...context,
548: 		title,
549: 	});
550: 	const past = date < TODAY;
551: 	const willPost = decision === "default" || decision === "overridden";
552: 	let delivery = store.deliveries.find(
553: 		(d) => d.trainingId === training.id && d.date === date,
554: 	);
555: 	if (past && !delivery) {
556: 		delivery = willPost
557: 			? {
558: 					trainingId: training.id,
559: 					date,
560: 					state: "delivered",
561: 					messageId: `14${date.replaceAll("-", "").slice(2)}…`,
562: 					threadId: `14${date.replaceAll("-", "").slice(2)}…`,
563: 					at: `${date}T${training.schedule.startTime}:03Z`,
