573: 	return {
574: 		key: `${training.id}@${date}`,
575: 		training,
576: 		date,
577: 		startTime: training.schedule.startTime,
578: 		endTime: training.schedule.endTime,
579: 		decision,
580: 		holiday,
581: 		suppression: decision === "suppressed" ? suppression : undefined,
582: 		override,
583: 		title,
584: 		messageSource,
585: 		rendered,
586: 		threadName: title,
