616: export function announcementsBetween(start: Date | string, end: Date | string) {
617: 	const from = dayjs(start);
618: 	const to = dayjs(end);
619: 	const result: HolidayAnnouncement[] = [];
620: 	for (const holiday of HOLIDAYS) {
621: 		const sameDay = dayjs(holiday.date);
622: 		const dayBefore = sameDay.subtract(1, "day");
623: 		for (const [phase, day] of [
624: 			["day_before", dayBefore],
625: 			["same_day", sameDay],
626: 		] as const) {
627: 			if (day.isBefore(from, "day") || !day.isBefore(to, "day")) continue;
628: 			const date = day.format(DATE_FORMAT);
629: 			result.push({
630: 				key: `holiday-${phase}@${date}`,
631: 				date,
632: 				holiday,
633: 				phase,
634: 				rendered: HOLIDAY_COPY[phase](holiday.name),
635: 				past: date < TODAY,
636: 				delivery:
637: 					date < TODAY
638: 						? {
639: 								trainingId: "holiday",
640: 								date,
641: 								state: "delivered",
642: 								messageId: `13${date.replaceAll("-", "").slice(2)}…`,
643: 							}
644: 						: undefined,
645: 			});
646: 		}
647: 	}
648: 	return result;
649: }
