from pathlib import Path
root = Path('apps/web')
ignored = {'node_modules','.svelte-kit','.cloudflare','.wrangler','.vitest-attachments','playwright-report','test-results','__screenshots__'}
counts = {'source':0,'tests':0,'other':0}
