    if not path.is_file() or any(part in ignored for part in path.parts):
        continue
    if path.suffix not in {'.ts','.js','.svelte','.json','.jsonc'}:
        continue
    rel = path.relative_to(root)
    if any(s in path.name for s in ('.test.','.spec.')) or rel.parts[0] in {'e2e','evals'}:
        counts['tests'] += 1
    elif rel.parts[0] == 'src':
        counts['source'] += 1
    else:
        counts['other'] += 1
print(counts)
