31: 	if (response.status !== 302 || !location) throw redirect(303, restartPath);
32: 
33: 	const destination = new URL(location);
34: 	if (
35: 		destination.origin !== url.origin ||
36: 		!destination.pathname.startsWith("/members/signup/")
